import{_ as r,l as i,o as e,c as n,v as t,p as s,x as l,d as p,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"Roll 模型","description":"","frontmatter":{"title":"Roll 模型","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/roll-model.md","filePath":"quant/roll-model.md","lastUpdated":1789023840000}'),h={name:"quant/roll-model.md"};function _(E,a,c,B,u,f){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="roll-模型" tabindex="-1">Roll 模型 <a class="header-anchor" href="#roll-模型" aria-label="Permalink to &quot;Roll 模型&quot;">​</a></h1><div class="epigraph"><p>若有效市场中的成交只是在固定的买卖报价之间来回跳动，观测到的价格序列应呈现负的一阶序列相关；有效价差可以从这段回跳的协方差里读出来。</p><footer>—— Roll, A Simple Implicit Measure of the Effective Bid-Ask Spread in an Efficient Market, Journal of Finance, 1984</footer></div><p><a href="/quant/market-fragmentation">上一课</a>把单场所 BBO 收成多场所拼装的 NBBO：有效价差对照哪一个中点，已经是规则输出。本课进入价格形成课序。报价会计仍以<a href="/quant/spread-decomposition">价差分解</a>为准，这里不再拆三项。缺口换成：没有可靠报价、或跨场所报价对不齐时，怎样只从成交价序列里估计有效价差。Roll 1984 年的答案依赖有效市场：价值是鞅，成交只在价值上下各半个价差处被记下，买卖方向独立。相邻成交倾向于一正一负，一阶协方差为负。它不解释价差从何而来——那是后面 <a href="/quant/glosten-milgrom">Glosten-Milgrom</a> 与 <a href="/quant/kyle-model">Kyle</a> 的工作——只在极强假设下给出一个隐含测度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/quant/spread-decomposition">价差分解</a>假定你看得见报价。许多市场或历史样本只有成交价，没有可靠的 BBO。报价价差即使存在，成交也可能发生在报价之内。若直接把相邻成交价的平均绝对差当价差，会把价值本身的波动算进去。缺口是一个识别策略：哪一部分差分来自价值，哪一部分来自买卖报价之间的弹跳。</p><p>Roll 的回答是：让价值保持有效，把全部可预测的负相关归因于弹跳。问题于是收成两条假设是否成立。第一，除价差外没有可预测性，中间价（价值）是鞅。第二，买卖方向不相关、与价值新息不相关，价差为常数。若知情交易让方向与后续价值同号，协方差会被推向正，弹跳测度失效。若存货让中点缓慢游走，也会污染同一矩。因此 Roll 首先是识别策略，其次才是一个数字公式。</p><h3 id="观测价格如何写成价值加弹跳" tabindex="-1">观测价格如何写成价值加弹跳 <a class="header-anchor" href="#观测价格如何写成价值加弹跳" aria-label="Permalink to &quot;观测价格如何写成价值加弹跳&quot;">​</a></h3><p>记不可见有效价值 \\(V_t\\) 为鞅，\\(\\Delta V_t\\) 均值为零、序列不相关。买卖方向 \\(Q_t\\in\\{+1,-1\\}\\)，+1 表示主动买、成交在卖价。有效价差为常数 \\(s\\)，则成交价</p> \\[P_t = V_t + \\frac{s}{2} Q_t. \\]<p>一阶差分 \\(\\Delta P_t=\\Delta V_t+(s/2)(Q_t-Q_{t-1})\\)。价差弹跳全部进入 \\((Q_t-Q_{t-1})\\)。若没有 \\(Q\\) 的数据，只能从 \\(\\Delta P\\) 的二阶矩里把 \\(s\\) 解出来。这就是「隐含」的意思：不观测报价，也不观测方向。</p><p><span class="marginnote">\\(P_t\\) 是成交价，不是中间价。把日收盘价或分钟 last 中间价直接代入，等于改写了采样。Roll 的对象是交易价格的弹跳；在 <a href="/quant/event-time">事件时间</a> 的成交序列上最接近原意。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设 \\(Q_t\\) 独立、对称，\\(\\mathrm{P}(Q_t=1)=1/2\\)，且与 \\(\\Delta V\\) 独立，\\(\\mathrm{Var}(Q_t)=1\\)。则</p> \\[\\mathrm{Cov}(\\Delta P_t,\\Delta P_{t-1}) = -\\left(\\frac{s}{2}\\right)^2 = -\\frac{s^2}{4}, \\]<p>因为 \\(\\Delta V\\) 不贡献相邻协方差，而 \\((Q_t-Q_{t-1})\\) 与 \\((Q_{t-1}-Q_{t-2})\\) 共享 \\(-Q_{t-1}\\) 这一项。于是</p> \\[s = 2\\sqrt{-\\mathrm{Cov}(\\Delta P_t,\\Delta P_{t-1})}. \\]<p>样本协方差若为负，开方即得估计；若为正，根号没有实数解，通常报告缺失或记为零，并解读为「弹跳被别的正自相关盖住」。这不是软件问题，是假设失败的诊断。估计应在成交事件序列上进行；先聚合成时钟格子会把格子内多次弹跳平均掉，协方差向零，估计的 \\(s\\) 偏小。</p><h3 id="与报价价差对照" tabindex="-1">与报价价差对照 <a class="header-anchor" href="#与报价价差对照" aria-label="Permalink to &quot;与报价价差对照&quot;">​</a></h3><p>有 BBO 时，可把 Roll 估计与平均报价价差、平均有效价差对照。一致，说明弹跳主导了成交价的一阶相关；Roll 更大，可能是成交价跳动超过报价（数据错误或延迟）；Roll 更小或失败，说明信息或存货诱导的正自相关在抢同一个协方差。Harris 讨论测量交易成本时，隐含测度的价值正在于没有报价的市场；有报价之后，它的角色变成设定检验，而不是首选测量。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制极其吝啬。价值不因成交而更新，方向不携带关于 \\(V\\) 的信息，流动性提供者每次赚到半个价差、下一次若方向反转再吐出或再赚——从价格路径看就是在 \\(V\\pm s/2\\) 之间弹。负一阶自相关是弹跳的签名，不是投资者非理性，也不是均值回复因子。O&#39;Hara 把这类摩擦看成在有效价值过程上叠加的微观结构噪声：噪声有结构（买卖两个点），所以不是白噪声，一阶相关为负。</p><p>一旦引入逆向选择，机制就变。成交为买，则 \\(V\\) 的条件期望上升，下一笔即使方向随机，价格的水平已经抬高，\\(\\Delta P\\) 的相邻乘积不必为负。Glosten-Milgrom 的报价本身就是条件期望，弹跳与更新缠在一起。Kyle 甚至没有固定的 \\(s\\)，价格是订单流的线性函数，相邻成交的协方差由信息揭示路径决定。Roll 公式在这些世界里不再是 \\(s\\) 的一致估计，它变成「若仍按弹跳解释，会被信息偏到哪一侧」的基准。</p><h3 id="协方差为正时发生了什么" tabindex="-1">协方差为正时发生了什么 <a class="header-anchor" href="#协方差为正时发生了什么" aria-label="Permalink to &quot;协方差为正时发生了什么&quot;">​</a></h3><p>样本 \\(\\mathrm{Cov}(\\Delta P_t,\\Delta P_{t-1})\\gt 0\\) 在日内高频并不罕见。可能的机制包括：方向持续（算法把大单切成一串同向成交）、价值新息本身在短窗口内正相关（公开信息逐步写入）、存货压力使中点沿同一方向调整、错误的成交时间戳把一笔拆成多笔同向。无论哪一种，开平方都没有经济含义。应停止报告虚假的 \\(s\\)，改描述方向持续性或改用报价数据去算有效价差。把正协方差强行取绝对值再开方，是在伪造弹跳。</p><p><span class="marginnote">Roll 估计的是有效价差的一个隐含水平，不是 <a href="/quant/spread-decomposition">价差分解</a> 里单独的处理成本。弹跳里可以混有存货的暂时成分；它明确排除的是使协方差变号的永久信息。</span></p>',25)),(e(),s(m,null,{default:l(()=>[d(o,{id:"mermaid-67",class:"mermaid",graph:"flowchart%20LR%0A%20%20V%5B%22%E9%9E%85%E4%BB%B7%E5%80%BC%20V%22%5D%20--%3E%20P%5B%22%E6%88%90%E4%BA%A4%E4%BB%B7%20P%20%3D%20V%20%2B%20(s%2F2)%20Q%22%5D%0A%20%20Q%5B%22%E7%8B%AC%E7%AB%8B%E4%B9%B0%E5%8D%96%E6%96%B9%E5%90%91%20Q%22%5D%20--%3E%20P%0A%20%20P%20--%3E%20D%5B%22%E5%B7%AE%E5%88%86%20%CE%94P%22%5D%0A%20%20D%20--%3E%20C%5B%22%E4%B8%80%E9%98%B6%E5%8D%8F%E6%96%B9%E5%B7%AE%E4%B8%BA%E8%B4%9F%22%5D%0A%20%20C%20--%3E%20S%5B%22s%20%3D%202%20sqrt(-Cov)%22%5D%0A%20%20INF%5B%22%E6%96%B9%E5%90%91%E6%90%BA%E5%B8%A6%E4%BF%A1%E6%81%AF%22%5D%20-.-%3E%7C%22%E5%8D%8F%E6%96%B9%E5%B7%AE%E4%B8%8A%E7%A7%BB%E7%94%9A%E8%87%B3%E5%8F%98%E6%AD%A3%22%7C%20C%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>常数价差、对称独立方向、价值鞅，三条同时成立的市场很少。它更像无信息、无存货或存货被充分对冲、方向被充分打散之后的极限。开盘、公告、有人用市价切片执行时，方向持续，Roll 失效。价格离散到一个 tick、成交长期停在同一价，差分大量为零，协方差被压低。隔夜收益不应与日内相邻成交接在同一条差分序列里。截面上对所有股票套用同一公式，热门股事件多、冷门股事件少，估计精度不可比。</p><p>Roll（1984）原文关心的是用日数据等相对低频序列去恢复有效价差，并讨论有效市场。把同一公式无改动地接到毫秒成交上，采样与微观结构噪声的形态都变了：你可能估到的是某一种弹跳，但不自动等于原文的对象。有 L1 报价时，优先用有效价差的直接算法，把 Roll 当对照；只有成交价时，必须报告协方差符号与样本长度，允许失败。它不能给出逆向选择份额，也不能给出 Kyle 的 \\(\\lambda\\)。</p><p><span class="marginnote">不要把「负自相关所以有价差」因果倒置。有价差弹跳可以产生负自相关；负自相关还可以来自许多别的均值回复。Roll 的识别靠的是把别的来源假设掉，而不是负相关本身证明了价差。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Roll（1984）在价值鞅、常数价差、独立等概率买卖下，用 \\(\\mathrm{Cov}(\\Delta P_t,\\Delta P_{t-1})=-s^2/4\\) 隐含估计有效价差。</li><li>公式应用在成交事件序列上；时钟聚合会削弱弹跳。</li><li>协方差为正时应拒绝该测度，而不是取绝对值；那是信息或方向持续的诊断。</li><li>它测量弹跳所隐含的有效价差，不分解逆向选择，也不替代报价上的有效价差。</li><li>与 Glosten-Milgrom、Kyle 的差别在于：成交不更新价值，价格不是订单流的反应函数。</li><li>离散价格、隔夜、切片执行与低频/高频采样构成适用边界。</li><li>出处：Roll, <em>Journal of Finance</em>, 1984；阅读框架见 O&#39;Hara, <em>Market Microstructure Theory</em> 与 Harris, <em>Trading and Exchanges</em>。</li></ul>',6))])}const A=r(h,[["render",_]]);export{D as __pageData,A as default};
